"""Verify source audits independently of the migration parser's extraction rules."""
from pathlib import Path
import sys

from migrator.evaluation.oracle_apex_parser import calls, data_inventory, ddl_inventory, gui_source_inventory
from besser.BUML.metamodel.structural import Class, DomainModel, IntegerType, Property


def test_ddl_audit_multiline_identity_blob_and_inline_foreign_key(tmp_path):
    (tmp_path / 'schema.sql').write_text('''
CREATE TABLE "PARENT" (
  "ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
  "NAME" VARCHAR2(40)
);
CREATE TABLE CHILD (
  ID NUMBER,
  PARENT_ID NUMBER CONSTRAINT parent_fk REFERENCES "PARENT" ON DELETE CASCADE,
  CONTENT BLOB,
  CREATED DATE
);
''', encoding='utf-8')
    result = ddl_inventory(tmp_path)
    assert result['counts'] == {'Entities': 2, 'Attributes': 4, 'Associations': 1,
                                'Multiplicities': 2, 'Generalizations': 0, 'Enumerations': 0}
    assert result['foreign_keys'] == [('child', ('parent_id',), 'parent')]
    assert result['tables']['child']['content']['type'] == 'blob'


def test_ddl_audit_deduplicates_tables_and_composite_constraints(tmp_path):
    ddl = '''CREATE TABLE PARENT (A NUMBER, B NUMBER);
CREATE TABLE CHILD (A NUMBER, B NUMBER, TITLE VARCHAR2(10),
CONSTRAINT fk FOREIGN KEY (A, B) REFERENCES PARENT (A, B));'''
    (tmp_path / 'one.sql').write_text(ddl, encoding='utf-8')
    (tmp_path / 'two.sql').write_text(ddl, encoding='utf-8')
    result = ddl_inventory(tmp_path)
    assert result['counts']['Entities'] == 2
    assert result['counts']['Attributes'] == 3
    assert result['counts']['Associations'] == 1


def test_extracted_attributes_exclude_identity_fk_and_added_fields(tmp_path):
    (tmp_path / 'schema.sql').write_text('''
CREATE TABLE EMP (ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
NAME VARCHAR2(40), DEPT_ID NUMBER REFERENCES DEPT, PHOTO BLOB);
CREATE TABLE DEPT (NAME VARCHAR2(40));
''', encoding='utf-8')
    source = ddl_inventory(tmp_path)
    domain = DomainModel(name='Example', types={
        Class(name='Emp', attributes={Property(name=name, type=IntegerType)
                                    for name in ['id', 'name', 'dept_id', 'generated_helper']}),
        Class(name='Dept', attributes={Property(name='name', type=IntegerType)}),
    })
    result = data_inventory(domain, source)
    assert result['counts']['Attributes'] == 2
    assert source['counts']['Attributes'] == 3
    assert result['classes']['Emp'] == ['name']
    assert {attribute['name']: attribute['reason'] for attribute in result['excluded_attributes']['Emp']} == {
        'id': 'platform_identity', 'dept_id': 'foreign_key', 'generated_helper': 'not_a_source_attribute'}


def test_gui_audit_counts_source_pages_bindings_forms_and_redirects(tmp_path):
    sql = """
wwv_flow_imp_page.create_page(p_id=>1,p_name=>'Home',p_page_mode=>'MODAL');
wwv_flow_imp_page.create_page_plug(p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select name', 'from EMP')));
wwv_flow_imp_page.create_page_item(p_name=>'P1_NAME',p_display_as=>'NATIVE_TEXT_FIELD');
wwv_flow_imp_page.create_page_button(p_button_name=>'SAVE',p_button_image_alt=>'Author''s change (',p_button_action=>'SUBMIT');
wwv_flow_imp_page.create_page_button(p_button_name=>'CANCEL',p_button_action=>'REDIRECT_PAGE',p_button_redirect_url=>'f?p=&APP_ID.:2:&SESSION.:');
wwv_flow_imp_page.create_page_branch(p_branch_action=>'3',p_branch_type=>'BRANCH_TO_STEP');
wwv_flow_imp_page.create_page_plug(p_plug_source=>'<p>SQL example: select * from DEPT</p>');
"""
    (tmp_path / 'page_00001.sql').write_text(sql, encoding='utf-8')
    parsed = calls(sql)
    assert parsed['create_page_button'][0]['button_image_alt'] == "Author's change ("
    result = gui_source_inventory(tmp_path, {'emp': {}, 'dept': {}})
    assert result['counts'] == {'Screens': 1, 'Bound entities': 1, 'Buttons': 2,
                                'Action types': 2, 'Navigation': 2, 'Forms': 1, 'Labels': 2}
